const String _sangeetaReferenceJpeg = '';
import 'dart:convert';
import 'dart:math' as math;

import 'package:flutter/material.dart';

import '../models/avatar_outfit.dart';

class SangeetaReferenceAvatar extends StatefulWidget {
  const SangeetaReferenceAvatar({
    required this.outfit,
    this.width = 120,
    this.height = 190,
    this.speaking = false,
    this.dancing = false,
    this.seated = false,
    super.key,
  });
  final AvatarOutfit outfit;
  final double width;
  final double height;
  final bool speaking;
  final bool dancing;
  final bool seated;

  @override
  State<SangeetaReferenceAvatar> createState() => _SangeetaReferenceAvatarState();
}

class _SangeetaReferenceAvatarState extends State<SangeetaReferenceAvatar>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      vsync: this,
      duration: Duration(milliseconds: widget.dancing ? 650 : 1450),
    )..repeat();
  }

  @override
  void didUpdateWidget(covariant SangeetaReferenceAvatar oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.dancing != widget.dancing) {
      _controller.duration = Duration(milliseconds: widget.dancing ? 650 : 1450);
    }
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: _controller,
      builder: (context, _) {
        final wave = math.sin(_controller.value * math.pi * 2);
        final sway = widget.dancing ? .025 * wave : .006 * wave;
        final lift = widget.dancing ? -5 * math.max(0.0, wave) : 0.0;
        final glow = widget.speaking ? .24 : widget.dancing ? .16 : .07;
        return Transform.translate(
          offset: Offset(widget.seated ? 0 : widget.width * sway, widget.seated ? 8 : lift),
          child: Transform.rotate(
            angle: sway,
            child: Container(
              width: widget.width,
              height: widget.height,
              decoration: BoxDecoration(
                borderRadius: BorderRadius.circular(widget.width * .16),
                border: Border.all(color: const Color(0xFFFFC857).withValues(alpha: .48)),
                boxShadow: [
                  BoxShadow(
                    color: const Color(0xFFFFC857).withValues(alpha: glow),
                    blurRadius: widget.speaking ? 28 : 18,
                    spreadRadius: widget.speaking ? 4 : 1,
                  ),
                ],
              ),
              clipBehavior: Clip.antiAlias,
              child: Stack(
                fit: StackFit.expand,
                children: [
                  Image.memory(
                    base64Decode(_sangeetaReferenceJpeg),
                    fit: BoxFit.cover,
                    filterQuality: FilterQuality.high,
                  ),
                  Positioned(
                    top: 0,
                    left: 0,
                    right: 0,
                    child: Container(
                      height: 3,
                      color: const Color(0xFFFFC857).withValues(
                        alpha: widget.speaking ? .95 : .24,
                      ),
                    ),
                  ),
                  if (widget.speaking)
                    Positioned(
                      left: widget.width * .18,
                      right: widget.width * .18,
                      bottom: widget.height * .045,
                      child: Row(
                        mainAxisAlignment: MainAxisAlignment.center,
                        children: [
                          for (final v in const [.18, .34, .60, .82, .48, .68, .30])
                            Expanded(
                              child: Container(
                                margin: const EdgeInsets.symmetric(horizontal: 2),
                                height: widget.height * v * .12,
                                decoration: BoxDecoration(
                                  color: const Color(0xFFFFC857),
                                  borderRadius: BorderRadius.circular(99),
                                ),
                              ),
                            ),
                        ],
                      ),
                    ),
                  if (widget.dancing)
                    const Positioned(
                      right: 8,
                      top: 8,
                      child: CircleAvatar(
                        radius: 15,
                        backgroundColor: Color(0xD9FFC857),
                        child: Icon(Icons.auto_awesome_rounded, size: 15, color: Colors.black),
                      ),
                    ),
                ],
              ),
            ),
          ),
        );
      },
    );
  }
}
